<script lang="ts">
  import { app, actions, isAdmin } from '#lib/state/app';
  import type { Outlet, Department, Position } from '#lib/types';
  import PageHeading from '#lib/components/PageHeading.svelte';
  import Icon from '#lib/components/Icon.svelte';
  import StatusPill from '#lib/components/StatusPill.svelte';
  import EmptyState from '#lib/components/EmptyState.svelte';
  import Modal from '#lib/components/Modal.svelte';
  import Feedback from '#lib/components/Feedback.svelte';
  let tab: 'outlets' | 'departments' | 'positions' = 'outlets';
  let editing = false, saving = false, locating = false, message = '', failed = false;
  let outlet: Partial<Outlet> = {}, department: Partial<Department> = {}, position: Partial<Position> = {};
  $: admin = isAdmin($app.user ?? undefined);
  const departmentName = (id: string) => $app.departments.find((d) => d.id === id)?.name ?? '—';
  function editOutlet(value?: Outlet) { outlet = value ? { ...value } : { name: '', address: '', active: true, isProduction: false, latitude: null, longitude: null, radiusMeters: 100, opensAt: '07:00', closesAt: '23:00', morningStart: '07:00', afternoonStart: '15:00', lateToleranceMinutes: 0 }; editing = true; message = ''; }
  function editDepartment(value?: Department) { department = value ? { ...value } : { name: '', code: '', active: true }; editing = true; message = ''; }
  function editPosition(value?: Position) { position = value ? { ...value } : { name: '', departmentId: '', active: true, isCashier: false }; editing = true; message = ''; }
  function add() { if (tab === 'outlets') editOutlet(); else if (tab === 'departments') editDepartment(); else editPosition(); }
  async function save() { saving = true; message = ''; try { if (tab === 'outlets') { if (outlet.latitude === null || outlet.latitude === undefined || outlet.longitude === null || outlet.longitude === undefined) throw new Error('Isi titik lokasi outlet. Lokasi diperlukan untuk validasi absensi.'); if (outlet.latitude < -90 || outlet.latitude > 90 || outlet.longitude < -180 || outlet.longitude > 180) throw new Error('Koordinat lokasi tidak valid.'); await actions.saveOutlet(outlet); } else if (tab === 'departments') await actions.saveDepartment(department); else await actions.savePosition(position); editing = false; failed = false; message = 'Perubahan berhasil disimpan.'; } catch (error) { failed = true; message = error instanceof Error ? error.message : 'Perubahan belum berhasil disimpan.'; } finally { saving = false; } }
  function useCurrentLocation() { if (!navigator.geolocation) { failed = true; message = 'Perangkat ini tidak mendukung pengambilan lokasi.'; return; } locating = true; navigator.geolocation.getCurrentPosition((location) => { outlet = { ...outlet, latitude: Number(location.coords.latitude.toFixed(7)), longitude: Number(location.coords.longitude.toFixed(7)) }; locating = false; failed = false; message = `Lokasi diambil dari perangkat (akurasi ±${Math.round(location.coords.accuracy)} meter). Pastikan Anda berada di outlet yang benar.`; }, (error) => { locating = false; failed = true; message = error.code === 1 ? 'Izinkan akses lokasi di pengaturan browser, lalu coba lagi.' : 'Lokasi tidak dapat diambil. Coba di area dengan sinyal lebih baik.'; }, { enableHighAccuracy: true, timeout: 20000, maximumAge: 0 }); }
</script>

<PageHeading eyebrow="PENGATURAN TIM" title="Organisasi & outlet" description="Kelola tempat kerja dan struktur tim Jabodetabek dari aplikasi.">{#if admin}<button class="btn btn-primary" on:click={add}><Icon name="plus" size={18}/>Tambah {tab === 'outlets' ? 'outlet' : tab === 'departments' ? 'departemen' : 'jabatan'}</button>{/if}</PageHeading>
{#if !admin}<EmptyState icon="shield" title="Akses khusus Admin HR" description="Hubungi Admin HR untuk perubahan outlet atau struktur pekerjaan."/>{:else}
  <div class="tabs" role="tablist" aria-label="Data organisasi"><button role="tab" aria-selected={tab === 'outlets'} class:active={tab === 'outlets'} on:click={() => tab = 'outlets'}><Icon name="building" size={17}/>Outlet <span>{$app.outlets.length}</span></button><button role="tab" aria-selected={tab === 'departments'} class:active={tab === 'departments'} on:click={() => tab = 'departments'}><Icon name="users" size={17}/>Departemen <span>{$app.departments.length}</span></button><button role="tab" aria-selected={tab === 'positions'} class:active={tab === 'positions'} on:click={() => tab = 'positions'}><Icon name="briefcase" size={17}/>Jabatan <span>{$app.positions.length}</span></button></div>
  <Feedback {message} error={failed}/>
  {#if tab === 'outlets'}<div class="outlet-grid">{#each $app.outlets as item}<article class="outlet-card panel"><div class="card-top"><span class="outlet-icon"><Icon name="building" size={24}/></span><StatusPill label={item.active ? 'Aktif' : 'Nonaktif'} tone={item.active ? 'green' : 'muted'}/></div><span class="code">{item.code} · JABODETABEK</span><h2>{item.name}</h2><p class="address">{item.address || 'Alamat belum dilengkapi'}</p><div class="outlet-meta"><div><Icon name="clock" size={16}/><span>{item.opensAt}–{item.closesAt} WIB</span></div><div><Icon name="pin" size={16}/><span>Radius {item.radiusMeters} meter</span></div>{#if item.isProduction}<div><Icon name="briefcase" size={16}/><span>Lokasi produksi</span></div>{/if}</div><div class="outlet-footer"><span>{$app.employees.filter((e) => e.outletId === item.id && e.status === 'active').length} karyawan aktif</span><button class="btn btn-secondary" on:click={() => editOutlet(item)}><Icon name="edit" size={15}/>Kelola</button></div></article>{/each}</div>{#if !$app.outlets.length}<EmptyState icon="building" title="Daftarkan outlet pertama" description="Atur jam operasional dan titik lokasi agar absensi dapat digunakan."/>{/if}
  {:else if tab === 'departments'}<section class="panel list">{#each $app.departments as item}<div class="master-row"><span class="master-icon"><Icon name="users"/></span><div class="master-info"><h3>{item.name}</h3><p>{item.code} · {$app.employees.filter((e) => e.departmentId === item.id && e.status === 'active').length} karyawan</p></div><StatusPill label={item.active ? 'Aktif' : 'Nonaktif'} tone={item.active ? 'green' : 'muted'}/><button class="btn btn-secondary" on:click={() => editDepartment(item)} aria-label={`Edit departemen ${item.name}`}><Icon name="edit" size={16}/><span class="edit-label">Edit</span></button></div>{/each}{#if !$app.departments.length}<EmptyState icon="users" title="Belum ada departemen" description="Tambahkan kelompok pekerjaan yang digunakan di Jabodetabek."/>{/if}</section>
  {:else}<section class="panel list">{#each $app.positions as item}<div class="master-row"><span class="master-icon"><Icon name="briefcase"/></span><div class="master-info"><h3>{item.name}</h3><p>{departmentName(item.departmentId)}{item.isCashier ? ' · Absensi kasir aktif' : ''}</p></div><StatusPill label={item.active ? 'Aktif' : 'Nonaktif'} tone={item.active ? 'green' : 'muted'}/><button class="btn btn-secondary" on:click={() => editPosition(item)} aria-label={`Edit jabatan ${item.name}`}><Icon name="edit" size={16}/><span class="edit-label">Edit</span></button></div>{/each}{#if !$app.positions.length}<EmptyState icon="briefcase" title="Belum ada jabatan" description="Tambahkan jabatan setelah departemennya tersedia."/>{/if}</section>{/if}
  <p class="footnote"><Icon name="info" size={15}/>Data yang sudah digunakan cukup dinonaktifkan agar riwayat tetap tersimpan.</p>
{/if}

<Modal open={editing} title={tab === 'outlets' ? outlet.id ? 'Kelola outlet' : 'Tambah outlet' : tab === 'departments' ? department.id ? 'Edit departemen' : 'Tambah departemen' : position.id ? 'Edit jabatan' : 'Tambah jabatan'} onclose={() => editing = false}>
  <form on:submit|preventDefault={save}>
    {#if tab === 'outlets'}
      <div class="form-grid"><label class="field span">Nama outlet<input class="input" bind:value={outlet.name} required/></label><label class="field span">Alamat<textarea class="textarea" bind:value={outlet.address} rows="2"></textarea></label><label class="field">Jam buka<input class="input" type="time" bind:value={outlet.opensAt} required/></label><label class="field">Jam tutup<input class="input" type="time" bind:value={outlet.closesAt} required/></label></div>
      <div class="form-section"><h3>Lokasi absensi</h3><p>Isi koordinat outlet atau gunakan posisi perangkat ketika berada di outlet.</p><button class="btn btn-secondary" type="button" on:click={useCurrentLocation} disabled={locating}><Icon name="pin" size={16}/>{locating ? 'Mencari lokasi…' : 'Gunakan lokasi saya'}</button><div class="form-grid coordinates"><label class="field">Latitude<input class="input" type="number" step="any" min="-90" max="90" bind:value={outlet.latitude} required/></label><label class="field">Longitude<input class="input" type="number" step="any" min="-180" max="180" bind:value={outlet.longitude} required/></label><label class="field span">Radius yang diizinkan (meter)<input class="input" type="number" min="10" max="2000" step="10" bind:value={outlet.radiusMeters} required/></label></div></div>
      <div class="form-section"><h3>Jam mulai shift kasir</h3><div class="form-grid"><label class="field">Pagi<input class="input" type="time" bind:value={outlet.morningStart} required/></label><label class="field">Sore<input class="input" type="time" bind:value={outlet.afternoonStart} required/></label><label class="field span">Toleransi keterlambatan (menit)<input class="input" type="number" min="0" max="120" bind:value={outlet.lateToleranceMinutes} required/></label></div><p>Durasi semua shift 8 jam termasuk istirahat. Shift Middle dimulai saat clock in.</p></div>
      <label class="check"><input type="checkbox" bind:checked={outlet.isProduction}/>Outlet ini juga menjadi tempat produksi</label><label class="check"><input type="checkbox" bind:checked={outlet.active}/>Outlet aktif</label>
    {:else if tab === 'departments'}<div class="form-grid"><label class="field span">Nama departemen<input class="input" bind:value={department.name} required/></label><label class="field span">Kode departemen<input class="input" bind:value={department.code} required maxlength="12" placeholder="Contoh: PRD"/></label></div><label class="check"><input type="checkbox" bind:checked={department.active}/>Departemen aktif</label>
    {:else}<div class="form-grid"><label class="field span">Nama jabatan<input class="input" bind:value={position.name} required/></label><label class="field span">Departemen<select class="select" bind:value={position.departmentId} required><option value="">Pilih departemen</option>{#each $app.departments.filter((d) => d.active || d.id === position.departmentId) as d}<option value={d.id}>{d.name}</option>{/each}</select></label></div><label class="check"><input type="checkbox" bind:checked={position.isCashier}/>Jabatan kasir — menggunakan clock in/out</label><label class="check"><input type="checkbox" bind:checked={position.active}/>Jabatan aktif</label>{/if}
    <Feedback {message} error={failed}/><div class="form-actions"><button class="btn btn-secondary" type="button" on:click={() => editing = false}>Batal</button><button class="btn btn-primary" type="submit" disabled={saving || locating}>{saving ? 'Menyimpan…' : 'Simpan perubahan'}</button></div>
  </form>
</Modal>

<style>
.tabs{display:flex;gap:.4rem;border-bottom:1px solid var(--border);margin-bottom:1.5rem;overflow-x:auto}.tabs button{display:flex;align-items:center;gap:.55rem;white-space:nowrap;padding:.9rem 1.2rem 1rem;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--muted);font-size:.82rem;cursor:pointer}.tabs button.active{color:var(--muted);border-bottom-color:#8c7d4e}.tabs span{font-size:.63rem;min-width:20px;padding:.15rem .35rem;border-radius:5px;background:#f5f0e1}.outlet-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.1rem}.outlet-card{padding:1.35rem;display:flex;flex-direction:column}.card-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:1.6rem}.outlet-icon,.master-icon{display:grid;place-items:center;background:#f6f2e4;color:var(--muted);border-radius:13px;width:48px;height:48px}.code{font-size:.59rem;color:var(--muted);letter-spacing:.1em}h2{font-size:1.15rem;margin:.6rem 0 .7rem;font-weight:600;letter-spacing:-.035em;color:var(--muted)}.address{font-size:.77rem;color:var(--muted);line-height:1.7;margin:0 0 1.1rem;min-height:2.6rem}.outlet-meta{display:grid;gap:.7rem;color:var(--muted);font-size:.74rem;margin-bottom:1.5rem}.outlet-meta>div{display:flex;align-items:center;gap:.6rem}.outlet-footer{border-top:1px solid var(--border);padding-top:1rem;display:flex;align-items:center;justify-content:space-between;gap:.5rem;margin-top:auto}.outlet-footer>span{font-size:.67rem;color:var(--muted)}.outlet-footer .btn{font-size:.7rem;padding:.55rem .8rem}.list{padding:0}.master-row{display:flex;align-items:center;gap:1rem;padding:1.1rem 1.3rem;border-bottom:1px solid var(--border)}.master-row:last-child{border-bottom:0}.master-icon{width:39px;height:39px;border-radius:11px}.master-info{flex:1}.master-info h3{font-size:.87rem;font-weight:600;margin:0 0 .4rem;color:var(--muted)}.master-info p{font-size:.71rem;color:var(--muted);margin:0}.footnote{display:flex;align-items:center;gap:.5rem;font-size:.71rem;color:var(--muted);margin:1.3rem 0}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.span{grid-column:1/-1}.form-section{padding-top:1.2rem;margin-top:1.2rem;border-top:1px solid var(--border)}.form-section h3{font-size:.86rem;font-weight:600;margin:0 0 .7rem}.form-section p{font-size:.74rem;line-height:1.65;color:var(--muted);margin:.7rem 0 1rem}.coordinates{margin-top:1rem}.check{display:flex;align-items:center;gap:.65rem;font-size:.8rem;margin:1rem 0;color:var(--muted)}.check input{accent-color:#7e7044}.form-actions{border-top:1px solid var(--border);padding-top:1.2rem;margin-top:1.2rem;display:flex;gap:.6rem;justify-content:flex-end}@media(max-width:1100px){.outlet-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.outlet-grid{grid-template-columns:1fr}.tabs button{font-size:.74rem;padding:.85rem .7rem;gap:.4rem}.master-row{gap:.7rem;padding:1rem}.master-info h3{font-size:.8rem}.master-info p{font-size:.65rem}.edit-label{display:none}.master-row .btn{padding:.55rem}.master-icon{display:none}.form-grid{gap:.8rem}.footnote{line-height:1.7;align-items:flex-start}}
  .tabs { border-bottom: 0; padding: .35rem .1rem .8rem; gap: .65rem; }
  .tabs button { border: 1px solid transparent; border-radius: 13px; min-height: 46px; padding: .9rem 1.2rem; }
  .tabs button.active { background: var(--surface); color: var(--accent); border-color: #ffffff7a; box-shadow: var(--inset); font-weight: 600; }
  .tabs span { background: #ece4c7; color: var(--accent); border-radius: 7px; }
  .outlet-icon, .master-icon { background: var(--surface); color: var(--accent); box-shadow: var(--raised-sm); border-radius: 15px; }
  h2, .master-info h3, .form-section h3 { color: var(--ink); }
  .outlet-meta { color: #5f5535; }
  .master-row .btn { min-width: 44px; min-height: 44px; }
  @media (max-width: 650px) { .tabs { gap: .4rem; } .tabs button { padding: .85rem .75rem; } }
</style>
